// Browser-test fixture: mounts the REAL compiled DusrelCrop
// component (see scripts/compile-fixture.mjs) and drives the
// package's process stores, bundled self-contained by tsdown
// and mounted by tests/browser/svelte.spec.ts.
import { mount } from "svelte";
// @ts-expect-error generated by scripts/compile-fixture.mjs at build time
import DusrelCrop from "./compiled/DusrelCrop.js";
import { createProcessImage } from "../src/index.js";
import type { CropRect } from "@dusrel/image-crop";

const rootEl = document.getElementById("root")!;
const cropOut = document.querySelector('[data-testid="crop"]')!;
const statusOut = document.querySelector('[data-testid="status"]')!;
const resultOut = document.querySelector('[data-testid="result"]')!;
const goBtn = document.querySelector<HTMLButtonElement>('[data-testid="go"]')!;

const stores = createProcessImage();
stores.status.subscribe((s) => {
  statusOut.textContent = s;
});
stores.result.subscribe((r) => {
  if (r) {
    resultOut.textContent = `${r.blob.type}:${r.blob.size}:${r.report.stepsApplied.join(",")}`;
  }
});
stores.error.subscribe((e) => {
  if (e) resultOut.textContent = `error:${String(e)}`;
});

let blob: Blob | undefined;
let crop: CropRect | undefined;

void (async () => {
  const canvas = new OffscreenCanvas(800, 600);
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgb(30, 100, 200)";
  ctx.fillRect(0, 0, 800, 600);
  ctx.fillStyle = "rgb(250, 200, 40)";
  ctx.fillRect(400, 0, 400, 600);
  blob = await canvas.convertToBlob({ type: "image/png" });
  const src = URL.createObjectURL(blob);
  mount(DusrelCrop, {
    target: rootEl,
    props: {
      src,
      style: "width:400px;height:300px;display:block",
      oncropchange: (c: CropRect) => {
        crop = c;
        cropOut.textContent = JSON.stringify(c);
      },
    },
  });
  goBtn.disabled = false;
})();

goBtn.addEventListener("click", () => {
  if (blob) {
    void stores.process(blob, {
      format: "image/webp",
      quality: 0.8,
      ...(crop ? { crop } : {}),
    });
  }
});
